class Solution {
public:
    string abbreviateProduct(int left, int right) {
        long long cnt2 = 0, cnt5 = 0, zeros = 0;
        long double logsum = 0.0L;
        long long suffix = 1;
        const long long MOD = 1000000000000LL; // keep enough digits for suffix handling

        auto strip2 = [&](long long x) {
            while (x % 2 == 0) {
                x /= 2;
                cnt2++;
            }
            return x;
        };
        auto strip5 = [&](long long x) {
            while (x % 5 == 0) {
                x /= 5;
                cnt5++;
            }
            return x;
        };

        for (int x = left; x <= right; ++x) {
            long long v = x;
            v = strip2(v);
            v = strip5(v);
            if (v == 0) continue;
            logsum += log10((long double)x);
            suffix = (suffix * v) % MOD;
        }

        zeros = min(cnt2, cnt5);
        long long extra2 = cnt2 - zeros;
        long long extra5 = cnt5 - zeros;

        // Build suffix of the non-zero part after removing all trailing zeros.
        auto mulmod = [&](long long a, long long b) -> long long {
            return (__int128)a * b % MOD;
        };

        for (long long i = 0; i < extra2; ++i) suffix = mulmod(suffix, 2);
        for (long long i = 0; i < extra5; ++i) suffix = mulmod(suffix, 5);

        // Remove any accidental trailing zeros in the tracked suffix.
        while (suffix % 10 == 0) suffix /= 10;

        // Determine number of digits after removing trailing zeros.
        long double totalLog = logsum + extra2 * log10((long double)2) + extra5 * log10((long double)5);
        long long digits = (long long)floor(totalLog + 1e-12L) + 1;

        string end = to_string(suffix);
        if ((int)end.size() > 10) {
            end = end.substr(0, 10);
        }

        if (digits <= 10) {
            // Need exact value; rebuild precisely for small digit counts.
            // Since digits <= 10, the non-zero product fits in 64-bit.
            __int128 exact = 1;
            for (int x = left; x <= right; ++x) exact *= x;
            long long z = 0;
            while (exact % 10 == 0) {
                exact /= 10;
                z++;
            }
            return to_string((long long)exact) + "e" + to_string(z);
        }

        // For large digit count, output first 10 digits and exponent.
        // We need the leading 10 digits of the non-zero product.
        long double frac = totalLog - floor(totalLog);
        long long lead = (long long)pow(10.0L, frac + 9.0L);

        return to_string(lead) + "e" + to_string(zeros);
    }
};
