class Solution {
public:
    int maxScore(vector<int>& nums) {
        int m = nums.size();
        vector<vector<int>> g(m, vector<int>(m, 0));
        for (int i = 0; i < m; ++i) {
            for (int j = i + 1; j < m; ++j) {
                g[i][j] = std::gcd(nums[i], nums[j]);
            }
        }

        int full = (1 << m) - 1;
        vector<int> dp(1 << m, 0);

        for (int mask = 0; mask <= full; ++mask) {
            int bits = __builtin_popcount((unsigned)mask);
            if (bits % 2) continue;
            int op = bits / 2 + 1;
            if (bits == m) continue;

            int first = -1;
            for (int i = 0; i < m; ++i) {
                if (!(mask & (1 << i))) {
                    first = i;
                    break;
                }
            }

            for (int j = first + 1; j < m; ++j) {
                if (mask & (1 << j)) continue;
                int nmask = mask | (1 << first) | (1 << j);
                dp[nmask] = max(dp[nmask], dp[mask] + op * g[first][j]);
            }
        }

        return dp[full];
    }
};
