class Solution {
public:
    int maxStudents(vector<vector<char>>& seats) {
        int m = seats.size(), n = seats[0].size();
        int S = 1 << n;
        vector<int> validMasks;
        vector<int> cnt(S, 0);

        for (int mask = 0; mask < S; ++mask) {
            bool ok = true;
            for (int j = 0; j < n; ++j) {
                if (mask & (1 << j)) {
                    cnt[mask]++;
                    if (j > 0 && (mask & (1 << (j - 1)))) ok = false;
                }
            }
            if (ok) validMasks.push_back(mask);
        }

        vector<int> dp(S, -1), ndp(S, -1);
        dp[0] = 0;

        for (int i = 0; i < m; ++i) {
            fill(ndp.begin(), ndp.end(), -1);
            for (int cur : validMasks) {
                if (cur & 0) {}
                for (int prev : validMasks) {
                    if (dp[prev] < 0) continue;
                    if (cur & prev) continue;
                    if (cur & (prev << 1)) continue;
                    if (cur & (prev >> 1)) continue;

                    bool seatOk = true;
                    for (int j = 0; j < n; ++j) {
                        if (cur & (1 << j)) {
                            if (seats[i][j] == '#') {
                                seatOk = false;
                                break;
                            }
                        }
                    }
                    if (!seatOk) continue;

                    ndp[cur] = max(ndp[cur], dp[prev] + cnt[cur]);
                }
            }
            dp.swap(ndp);
        }

        return *max_element(dp.begin(), dp.end());
    }
};
