class Solution {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        int n = (int)flowers.size();
        sort(flowers.begin(), flowers.end());

        int complete0 = 0;
        while (complete0 < n && flowers[complete0] < target) complete0++;
        int m = complete0;

        vector<long long> pref(m + 1, 0);
        for (int i = 0; i < m; ++i) pref[i + 1] = pref[i] + flowers[i];

        auto costToRaise = [&](int k, long long x) -> long long {
            if (k <= 0) return 0;
            int pos = upper_bound(flowers.begin(), flowers.begin() + k, (int)x) - flowers.begin();
            long long need = x * pos - pref[pos];
            return need;
        };

        auto maxMinForK = [&](int k, long long budget) -> long long {
            if (k <= 0) return 0;
            long long lo = 0, hi = target - 1;
            while (lo < hi) {
                long long mid = (lo + hi + 1) >> 1;
                if (costToRaise(k, mid) <= budget) lo = mid;
                else hi = mid - 1;
            }
            return lo;
        };

        long long ans = 0;
        long long suffixCost = 0; // cost to make last t gardens complete among all gardens
        int t = 0;

        for (int completeCnt = 0; completeCnt <= n; ++completeCnt) {
            if (completeCnt > 0) {
                int idx = n - completeCnt;
                if (flowers[idx] >= target) {
                    // already complete, no cost
                } else {
                    suffixCost += target - flowers[idx];
                }
            }
            if (suffixCost > newFlowers) continue;

            int incompleteCnt = n - completeCnt;
            long long budget = newFlowers - suffixCost;
            long long cur = 1LL * completeCnt * full;

            if (incompleteCnt > 0 && partial > 0) {
                long long mn = maxMinForK(incompleteCnt, budget);
                cur += mn * 1LL * partial;
            }
            ans = max(ans, cur);
        }

        return ans;
    }
};
