class Solution {
public:
    int minMalwareSpread(vector<vector<int>>& graph, vector<int>& initial) {
        int n = (int)graph.size();
        sort(initial.begin(), initial.end());
        vector<int> color(n, -1);
        vector<int> compSize;

        int cid = 0;
        for (int i = 0; i < n; ++i) {
            if (color[i] != -1) continue;
            queue<int> q;
            q.push(i);
            color[i] = cid;
            int sz = 0;
            while (!q.empty()) {
                int u = q.front(); q.pop();
                ++sz;
                for (int v = 0; v < n; ++v) {
                    if (graph[u][v] && color[v] == -1) {
                        color[v] = cid;
                        q.push(v);
                    }
                }
            }
            compSize.push_back(sz);
            ++cid;
        }

        vector<int> infectedCount(cid, 0);
        for (int x : initial) infectedCount[color[x]]++;

        int ans = initial[0];
        int bestSaved = -1;

        for (int x : initial) {
            int c = color[x];
            if (infectedCount[c] == 1) {
                int saved = compSize[c];
                if (saved > bestSaved || (saved == bestSaved && x < ans)) {
                    bestSaved = saved;
                    ans = x;
                }
            }
        }

        return ans;
    }
};
