class Solution {
public:
    int minAreaRect(vector<vector<int>>& points) {
        unordered_map<int, vector<int>> mp;
        for (auto &p : points) mp[p[0]].push_back(p[1]);

        unordered_map<long long, int> last;
        int ans = INT_MAX;

        for (auto &kv : mp) {
            auto &ys = kv.second;
            sort(ys.begin(), ys.end());
            int m = ys.size();
            for (int i = 0; i < m; ++i) {
                for (int j = i + 1; j < m; ++j) {
                    long long key = (long long)ys[i] * 40001LL + ys[j];
                    if (last.count(key)) {
                        int prevX = last[key];
                        ans = min(ans, (kv.first - prevX) * (ys[j] - ys[i]));
                    }
                    last[key] = kv.first;
                }
            }
        }

        return ans == INT_MAX ? 0 : ans;
    }
};
