            vector<int> res;
            int used[10] = {0};

            function<void(int,int,int)> dfs = [&](int len, int sum, int mask) {
                if (sum > 7) return;
                if (len == 0) {
                    if (sum == 0) return;
                    string s;
                    for (int d = 1; d <= 7; ++d) {
                        if (mask & (1 << d)) s.append(d, char('0' + d));
                    }
                    sort(s.begin(), s.end());
                    do {
                        if (s[0] != '0') res.push_back(stoi(s));
                    } while (next_permutation(s.begin(), s.end()));
                    return;
                }
                for (int d = 1; d <= 7; ++d) {
                    if (!(mask & (1 << d))) {
                        if (sum + d <= 7) dfs(len - 1, sum + d, mask | (1 << d));
                    }
                }
            };

            for (int mask = 1; mask < (1 << 8); ++mask) {
                int sum = 0;
                for (int d = 1; d <= 7; ++d) if (mask & (1 << d)) sum += d;
                if (sum > 7) continue;
                string s;
                for (int d = 1; d <= 7; ++d) if (mask & (1 << d)) s.append(d, char('0' + d));
