        if (sum % k != 0) return false;
        int target = sum / k;

        sort(nums.rbegin(), nums.rend());
        if (nums[0] > target) return false;

        int fullMask = (1 << n) - 1;
        vector<int> memo(1 << n, -1);

        function<bool(int, int)> dfs = [&](int mask, int currSum) -> bool {
            if (mask == fullMask) return true;
            int &res = memo[mask];
            if (res != -1 && currSum == 0) return res;

            if (currSum == target) {
                bool ans = dfs(mask, 0);
                if (currSum == 0) res = ans;
                return ans;
            }

            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) continue;
                if (currSum + nums[i] > target) continue;
                if (dfs(mask | (1 << i), currSum + nums[i])) {
                    if (currSum == 0) res = 1;
                    return true;
                }
            }

            if (currSum == 0) res = 0;
            return false;
        };

        return dfs(0, 0);
    }
