public:
    int regionsBySlashes(vector<string>& grid) {
        int n = grid.size();
        int m = n * n * 4;
        vector<int> parent(m), sz(m, 1);
        iota(parent.begin(), parent.end(), 0);

        auto find = [&](int x) {
            int root = x;
            while (parent[root] != root) root = parent[root];
            while (parent[x] != x) {
                int p = parent[x];
                parent[x] = root;
                x = p;
            }
            return root;
        };

        auto unite = [&](int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (sz[a] < sz[b]) swap(a, b);
            parent[b] = a;
            sz[a] += sz[b];
        };

        auto id = [&](int i, int j, int k) {
            return (i * n + j) * 4 + k;
        };

        for (int i = 0; i < n; ++i) {
