                char c = grid[i][j];
                int a = id(i, j, 0);
                int b = id(i, j, 1);
                int c2 = id(i, j, 2);
                int d = id(i, j, 3);

                if (c == ' ') {
                    unite(a, b);
                    unite(b, c2);
                    unite(c2, d);
