class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        int n = target.size();
        vector<array<int,26>> st;
        for (auto &s : stickers) {
            array<int,26> cnt{};
            for (char c : s) cnt[c - 'a']++;
            st.push_back(cnt);
        }

        unordered_map<int, int> memo;
        memo[0] = 0;

        function<int(int)> dfs = [&](int mask) -> int {
            if (memo.count(mask)) return memo[mask];

            int first = 0;
            while (first < n && (mask & (1 << first))) first++;

            array<int,26> need{};
            for (int i = 0; i < n; i++) {
                if (!(mask & (1 << i))) need[target[i] - 'a']++;
            }

            int ans = INT_MAX / 2;
            for (const auto &cnt : st) {
                if (cnt[target[first] - 'a'] == 0) continue;

                int newMask = mask;
                array<int,26> left = need;
                for (int c = 0; c < 26; c++) {
                    int use = min(left[c], cnt[c]);
                    left[c] -= use;
                }

                for (int i = 0; i < n; i++) {
                    if (!(newMask & (1 << i))) {
                        int ch = target[i] - 'a';
                        if (left[ch] > 0) {
                            left[ch]--;
                            newMask |= (1 << i);
                        }
                    }
                }

                int sub = dfs(newMask);
                if (sub != -1) ans = min(ans, 1 + sub);
            }

            memo[mask] = (ans >= INT_MAX / 2 ? -1 : ans);
            return memo[mask];
        };

        return dfs(0);
    }
};
