public:
    bool isSolvable(vector<string>& words, string result) {
        vector<int> coef(26, 0);
        vector<bool> leading(26, false);
        int n = words.size();

        for (auto &w : words) {
            if (w.size() > 1) leading[w[0] - 'A'] = true;
            for (int i = 0; i < (int)w.size(); ++i) {
                coef[w[i] - 'A'] += (int)pow(10, w.size() - 1 - i);
            }
        }

        if (result.size() > 1) leading[result[0] - 'A'] = true;
        for (int i = 0; i < (int)result.size(); ++i) {
            coef[result[i] - 'A'] -= (int)pow(10, result.size() - 1 - i);
        }

        vector<int> letters;
        for (int c = 0; c < 26; ++c) if (coef[c] != 0) letters.push_back(c);

        sort(letters.begin(), letters.end(), [&](int a, int b) {
            return abs(coef[a]) > abs(coef[b]);
        });

        vector<int> assign(26, -1);
        vector<bool> used(10, false);

        function<bool(int)> dfs = [&](int idx) -> bool {
            if (idx == (int)letters.size()) return true;

            int c = letters[idx];
            for (int d = 0; d <= 9; ++d) {
                if (used[d]) continue;
                if (d == 0 && leading[c]) continue;
                used[d] = true;
                assign[c] = d;
                if (dfs(idx + 1)) return true;
                assign[c] = -1;
                used[d] = false;
            }
            return false;
        };

        return dfs(0);
    }
};
