class Solution {
public:
    int numFactoredBinaryTrees(vector<int>& arr) {
        const long long MOD = 1000000007LL;
        sort(arr.begin(), arr.end());

        int n = (int)arr.size();
        unordered_map<long long, int> idx;
        idx.reserve(n * 2);
        for (int i = 0; i < n; ++i) idx[arr[i]] = i;

        vector<long long> dp(n, 1); // single-node tree

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < i; ++j) {
                if (arr[i] % arr[j] != 0) continue;
                long long other = arr[i] / arr[j];
                auto it = idx.find(other);
                if (it == idx.end()) continue;
                int k = it->second;
                if (k > i) continue;
                dp[i] = (dp[i] + dp[j] * dp[k]) % MOD;
            }
        }

        long long ans = 0;
        for (long long x : dp) ans = (ans + x) % MOD;
        return (int)ans;
    }
};
