class Solution {
public:
    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {
        int m = grid.size(), n = grid[0].size();
        int N = m * n;
        vector<int> g;
        g.reserve(N);
        for (auto &row : grid) for (int x : row) g.push_back(x);

        vector<int> removed(hits.size(), 0);
        for (int i = 0; i < (int)hits.size(); ++i) {
            int r = hits[i][0], c = hits[i][1];
            int idx = r * n + c;
            if (g[idx] == 1) {
                g[idx] = 0;
                removed[i] = 1;
            }
        }

        vector<int> parent(N + 1), sz(N + 1, 1);
        iota(parent.begin(), parent.end(), 0);

        function<int(int)> find = [&](int x) -> int {
            return parent[x] == x ? x : parent[x] = find(parent[x]);
        };

        auto unite = [&](int a, int b) {
            a = find(a); b = find(b);
            if (a == b) return;
            if (sz[a] < sz[b]) swap(a, b);
            parent[b] = a;
            sz[a] += sz[b];
        };

        int roof = N;
        auto id = [&](int r, int c) { return r * n + c; };

        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (g[id(r, c)] == 0) continue;
                if (r == 0) unite(id(r, c), roof);
                if (r > 0 && g[id(r - 1, c)] == 1) unite(id(r, c), id(r - 1, c));
                if (c > 0 && g[id(r, c - 1)] == 1) unite(id(r, c), id(r, c - 1));
            }
        }

        vector<int> ans(hits.size(), 0);
        int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};

        for (int i = (int)hits.size() - 1; i >= 0; --i) {
            int r = hits[i][0], c = hits[i][1];
            int idx = id(r, c);
            if (!removed[i]) {
                ans[i] = 0;
                continue;
            }

            int before = sz[find(roof)];
            g[idx] = 1;

            if (r == 0) unite(idx, roof);
            for (auto &d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                int nidx = id(nr, nc);
                if (g[nidx] == 1) unite(idx, nidx);
            }

            int after = sz[find(roof)];
            ans[i] = max(0, after - before - 1);
        }

        return ans;
    }
};
