            int node = q.front();
            q.pop();
            safe[node] = true;

            for (int prev : rev[node]) {
                if (--outdeg[prev] == 0) {
                    q.push(prev);
                }
            }
        }

        vector<int> ans;
        for (int i = 0; i < n; ++i) {
            if (safe[i]) ans.push_back(i);
