            sumMid += a;
            lo.insert(b);
            mid.insert(a);
        }
        while (!mid.empty() && !hi.empty() && *prev(mid.end()) > *hi.begin()) {
            int a = *prev(mid.end());
            int b = *hi.begin();
            mid.erase(prev(mid.end()));
