public:
    MKAverage(int m, int k) : m(m), k(k) {}

    void addElement(int num) {
        q.push_back(num);

        if (lo.empty() || num <= *prev(lo.end())) {
            lo.insert(num);
        } else if (!hi.empty() && num >= *hi.begin()) {
            hi.insert(num);
        } else {
            mid.insert(num);
            sumMid += num;
        }

        if ((int)q.size() > m) {
            int old = q.front();
            q.pop_front();
            auto it = lo.find(old);
            if (it != lo.end()) {
                lo.erase(it);
            } else {
                it = hi.find(old);
                if (it != hi.end()) {
                    hi.erase(it);
                } else {
                    it = mid.find(old);
                    mid.erase(it);
                    sumMid -= old;
                }
            }
        }

        rebalance();
    }

    int calculateMKAverage() {
        if ((int)q.size() < m) return -1;
        return (int)(sumMid / (m - 2 * k));
    }
