class Solution {
public:
    int largestMagicSquare(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> row(m, vector<int>(n + 1, 0)), col(m + 1, vector<int>(n, 0));

        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                row[i][j + 1] = row[i][j] + grid[i][j];
                col[i + 1][j] = col[i][j] + grid[i][j];
            }
        }

        auto sumRow = [&](int r, int l, int rr) {
            return row[r][rr] - row[r][l];
        };
        auto sumCol = [&](int c, int l, int rr) {
            return col[rr][c] - col[l][c];
        };

        int maxK = min(m, n);
        for (int k = maxK; k >= 1; --k) {
            for (int i = 0; i + k <= m; ++i) {
                for (int j = 0; j + k <= n; ++j) {
                    int target = sumRow(i, j, j + k);
                    bool ok = true;

                    for (int r = i; r < i + k && ok; ++r) {
                        if (sumRow(r, j, j + k) != target) ok = false;
                    }
                    for (int c = j; c < j + k && ok; ++c) {
                        if (sumCol(c, i, i + k) != target) ok = false;
                    }

                    int d1 = 0, d2 = 0;
                    for (int t = 0; t < k; ++t) {
                        d1 += grid[i + t][j + t];
                        d2 += grid[i + t][j + k - 1 - t];
                    }
                    if (ok && d1 == target && d2 == target) return k;
                }
            }
        }
        return 1;
    }
};
