class Solution {
public:
    int maximumANDSum(vector<int>& nums, int numSlots) {
        int n = nums.size();
        int m = numSlots;
        int totalStates = 1;
        for (int i = 0; i < m; ++i) totalStates *= 3;

        vector<int> pow3(m + 1, 1);
        for (int i = 1; i <= m; ++i) pow3[i] = pow3[i - 1] * 3;

        vector<int> dp(totalStates, -1);
        dp[0] = 0;

        for (int x : nums) {
            vector<int> ndp = dp;
            for (int mask = 0; mask < totalStates; ++mask) {
                if (dp[mask] < 0) continue;
                for (int slot = 0; slot < m; ++slot) {
                    int cnt = (mask / pow3[slot]) % 3;
                    if (cnt < 2) {
                        int nmask = mask + pow3[slot];
                        ndp[nmask] = max(ndp[nmask], dp[mask] + (x & (slot + 1)));
                    }
                }
            }
            dp.swap(ndp);
        }

        return *max_element(dp.begin(), dp.end());
    }
};
