class Solution {
public:
    int maxCompatibilitySum(vector<vector<int>>& students, vector<vector<int>>& mentors) {
        int m = students.size(), n = students[0].size();
        vector<vector<int>> score(m, vector<int>(m, 0));
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < m; ++j) {
                int c = 0;
                for (int k = 0; k < n; ++k) {
                    if (students[i][k] == mentors[j][k]) ++c;
                }
                score[i][j] = c;
            }
        }

        int N = 1 << m;
        vector<int> dp(N, -1);
        dp[0] = 0;
        for (int mask = 0; mask < N; ++mask) {
            int i = __builtin_popcount((unsigned)mask);
            if (i >= m || dp[mask] < 0) continue;
            for (int j = 0; j < m; ++j) {
                if (!(mask & (1 << j))) {
                    int nmask = mask | (1 << j);
                    dp[nmask] = max(dp[nmask], dp[mask] + score[i][j]);
                }
            }
        }
        return dp[N - 1];
    }
};
