        auto countPairs = [](const vector<int>& a, const vector<int>& b) -> long long {
            unordered_map<long long, long long> freq;
            for (int x : b) freq[x]++;
            long long ans = 0;
            for (int x : a) {
                long long target = 1LL * x * x;
                for (const auto& [v, cnt] : freq) {
