                    if (it == freq.end()) continue;
                    if (u == v) ans += cnt * (cnt - 1) / 2;
                    else ans += cnt * it->second;
                }
            }
            return ans;
        };

        long long res = countPairs(nums1, nums2) + countPairs(nums2, nums1);
        return (int)res;
    }
