    vector<string> removeInvalidParentheses(string s) {
        int leftRemove = 0, rightRemove = 0;
        for (char c : s) {
            if (c == '(') {
                leftRemove++;
            } else if (c == ')') {
                if (leftRemove > 0) leftRemove--;
                else rightRemove++;
            }
        }

        unordered_set<string> visited;
        vector<string> res;
        int n = (int)s.size();
        int best = -1;

        function<void(int,int,int,int,string&)> dfs = [&](int idx, int open, int lrem, int rrem, string& cur) {
            if (idx == n) {
                if (open == 0 && lrem == 0 && rrem == 0) {
                    if (best == -1 || (int)cur.size() > best) {
                        best = (int)cur.size();
                        res.clear();
                        res.push_back(cur);
                    } else if ((int)cur.size() == best) {
                        res.push_back(cur);
                    }
                }
                return;
