            char c = s[idx];
            int remaining = n - idx;
            if ((int)cur.size() + remaining < best) return;

            if (c == '(') {
                if (lrem > 0) {
                    dfs(idx + 1, open, lrem - 1, rrem, cur);
                }
                cur.push_back(c);
                dfs(idx + 1, open + 1, lrem, rrem, cur);
                cur.pop_back();
            } else if (c == ')') {
