                    dfs(idx + 1, open, lrem - 1, rrem, cur);
                }
                cur.push_back(c);
                dfs(idx + 1, open + 1, lrem, rrem, cur);
                cur.pop_back();
            } else if (c == ')') {
                if (rrem > 0) {
                    dfs(idx + 1, open, lrem, rrem - 1, cur);
                }
                if (open > 0) {
                    cur.push_back(c);
                    dfs(idx + 1, open - 1, lrem, rrem, cur);
                    cur.pop_back();
                }
            } else {
                cur.push_back(c);
                dfs(idx + 1, open, lrem, rrem, cur);
                cur.pop_back();
            }
        };

        string cur;
        dfs(0, 0, leftRemove, rightRemove, cur);

        unordered_set<string> uniq;
        vector<string> ans;
        for (auto &x : res) {
            if (uniq.insert(x).second) ans.push_back(x);
        }
        if (ans.empty()) ans.push_back("");
        return ans;
    }
