class Solution {
public:
    vector<double> medianSlidingWindow(vector<int>& nums, int k) {
        multiset<long long> lo, hi; // lo: smaller half, hi: larger half

        auto balance = [&]() {
            while (lo.size() > hi.size() + 1) {
                auto it = prev(lo.end());
                hi.insert(*it);
                lo.erase(it);
            }
            while (lo.size() < hi.size()) {
                auto it = hi.begin();
                lo.insert(*it);
                hi.erase(it);
            }
        };

        auto add = [&](long long x) {
            if (lo.empty() || x <= *prev(lo.end())) lo.insert(x);
            else hi.insert(x);
            balance();
        };

        auto remove = [&](long long x) {
            auto it = lo.find(x);
            if (it != lo.end()) lo.erase(it);
            else {
                it = hi.find(x);
                hi.erase(it);
            }
            balance();
        };

        vector<double> ans;
        ans.reserve(nums.size() - k + 1);

        for (int i = 0; i < nums.size(); ++i) {
            add(nums[i]);
            if (i >= k) remove(nums[i - k]);

            if (i >= k - 1) {
                if (k % 2 == 1) {
                    ans.push_back((double)*prev(lo.end()));
                } else {
                    double a = (double)*prev(lo.end());
                    double b = (double)*hi.begin();
                    ans.push_back((a + b) / 2.0);
                }
            }
        }

        return ans;
    }
};
