class StreamChecker {
    struct Node {
        int next[26];
        bool end;
        Node() : end(false) {
            for (int i = 0; i < 26; ++i) next[i] = -1;
        }
    };

    vector<Node> trie;
    vector<char> stream;
    int maxLen;

public:
    StreamChecker(vector<string>& words) {
        trie.emplace_back();
        maxLen = 0;
        for (const string& w : words) {
            maxLen = max(maxLen, (int)w.size());
            int node = 0;
            for (int i = (int)w.size() - 1; i >= 0; --i) {
                int c = w[i] - 'a';
                if (trie[node].next[c] == -1) {
                    trie[node].next[c] = (int)trie.size();
                    trie.emplace_back();
                }
                node = trie[node].next[c];
            }
            trie[node].end = true;
        }
    }

    bool query(char letter) {
        stream.push_back(letter);
        int node = 0;
        for (int i = (int)stream.size() - 1, steps = 0; i >= 0 && steps < maxLen; --i, ++steps) {
            int c = stream[i] - 'a';
            if (trie[node].next[c] == -1) return false;
            node = trie[node].next[c];
            if (trie[node].end) return true;
        }
        return false;
    }
};

