public:
    bool validateBinaryTreeNodes(int n, vector<int>& leftChild, vector<int>& rightChild) {
        vector<int> indeg(n, 0);

        for (int i = 0; i < n; ++i) {
            if (leftChild[i] != -1) {
                if (++indeg[leftChild[i]] > 1) return false;
            }
            if (rightChild[i] != -1) {
                if (++indeg[rightChild[i]] > 1) return false;
            }
        }

        int root = -1;
        for (int i = 0; i < n; ++i) {
            if (indeg[i] == 0) {
                if (root != -1) return false;
                root = i;
            }
        }
        if (root == -1) return false;

        vector<int> vis(n, 0);
        queue<int> q;
        q.push(root);
        vis[root] = 1;
        int count = 0;

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            ++count;

            int l = leftChild[u], r = rightChild[u];
            if (l != -1) {
                if (vis[l]) return false;
                vis[l] = 1;
                q.push(l);
            }
            if (r != -1) {
                if (vis[r]) return false;
                vis[r] = 1;
                q.push(r);
            }
        }

        return count == n;
    }
};
