class Solution {
public:
    bool isMatch(string s, string p) {
        int n = s.size(), m = p.size();

        string np;
        for (char c : p) {
            if (c == '*' && !np.empty() && np.back() == '*') continue;
            np.push_back(c);
        }
        p.swap(np);
        m = p.size();

        vector<vector<char>> dp(n + 1, vector<char>(m + 1, 0));
        dp[0][0] = 1;

        for (int j = 1; j <= m; ++j) {
            if (p[j - 1] == '*') dp[0][j] = dp[0][j - 1];
        }

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= m; ++j) {
                if (p[j - 1] == '*') {
                    dp[i][j] = dp[i][j - 1] || dp[i - 1][j];
                } else if (p[j - 1] == '?' || p[j - 1] == s[i - 1]) {
                    dp[i][j] = dp[i - 1][j - 1];
                }
            }
        }

        return dp[n][m];
    }
};
